mapper.select:
WITH RECURSIVE destination_regions AS ( SELECT d.id AS destination_id, region.id AS region_id, region.parent_id, region.region_name, region.code, region.is_visible, SUBSTRING_INDEX(region.code, '-', 1) AS country_code FROM destinations d JOIN country_categories region ON region.id = d.region_id WHERE d.is_public = 1 AND d.region_id IN
#{id}
UNION ALL
SELECT destination_regions.destination_id, parent.id AS region_id, parent.parent_id, parent.region_name, parent.code, parent.is_visible, destination_regions.country_code FROM destination_regions JOIN country_categories parent ON parent.id = destination_regions.parent_id ), destination_countries AS ( SELECT destination_regions.destination_id, destination_regions.region_id AS country_id, destination_regions.region_name AS country_name FROM destination_regions WHERE destination_regions.code = destination_regions.country_code AND ( destination_regions.parent_id IS NOT NULL OR EXISTS ( SELECT 1 FROM country_categories country_child WHERE country_child.parent_id = destination_regions.region_id AND country_child.code LIKE CONCAT(destination_regions.code, '-%') ) ) ) SELECT d.id AS destination_id, dt.name, dt.short_description,
( SELECT di.image_url FROM destination_images di WHERE di.destination_id = d.id AND di.is_main = 1 ORDER BY di.order_index ASC, di.id ASC LIMIT 1 ) AS image_url, destination_countries.country_id, destination_countries.country_name, d.region_id AS region_id, region.region_name FROM destinations d JOIN destination_translations dt ON dt.destination_id = d.id AND dt.language_code = 'ko' JOIN country_categories region ON region.id = d.region_id JOIN destination_countries ON destination_countries.destination_id = d.id WHERE d.is_public = 1 AND d.region_id IN
#{id}
AND NOT EXISTS ( SELECT 1 FROM destination_regions hidden_path WHERE hidden_path.destination_id = d.id AND COALESCE(hidden_path.is_visible, 1) != 1 ) ORDER BY RAND() LIMIT #{limit}

WITH RECURSIVE country_regions AS ( SELECT country.id AS country_id, country.id AS region_id FROM country_categories country WHERE country.id IN
#{id}
AND country.is_visible = 1
UNION ALL
SELECT country_regions.country_id, child.id AS region_id FROM country_regions JOIN country_categories child ON child.parent_id = country_regions.region_id AND child.is_visible = 1 ), eligible_countries AS ( SELECT DISTINCT country.id AS country_id, country.region_name AS country_name FROM country_categories country JOIN country_regions ON country_regions.country_id = country.id JOIN destinations destination ON destination.region_id = country_regions.region_id AND destination.is_public = 1 JOIN destination_translations translation ON translation.destination_id = destination.id AND translation.language_code = 'ko' WHERE country.id IN
#{id}
) SELECT eligible_countries.country_id, eligible_countries.country_name, eligible_countries.country_id AS region_id, eligible_countries.country_name AS region_name FROM eligible_countries ORDER BY
CASE WHEN EXISTS ( SELECT 1 FROM country_regions excluded_region WHERE excluded_region.country_id = eligible_countries.country_id AND excluded_region.region_id = #{excludeRegionId} ) THEN 1 ELSE 0 END,
RAND() LIMIT 1
